// SkuNormalisation.jsx
// Two tabs: Distributor | Modern Trade
// Tree: Category → Family → Canonical SKU → Raw mappings (with source)
// Add / Edit / Delete canonical SKUs and mappings
// Unmapped SKUs section at bottom

import { useState, useEffect, useCallback } from "react";
import {
  getSkuCanonical, getSkuUnmapped,
  createSkuCanonical, updateSkuCanonical, deleteSkuCanonical,
  createSkuMapping, deleteSkuMapping,
} from "../services/api";

const CATEGORIES = ["Namkeen", "Khakhara"];

// ── Category badge colours ─────────────────────────────────────────────────
const CAT_STYLE = {
  Namkeen:  { bg: "rgba(16,185,129,0.1)",  color: "#10B981" },
  Khakhara: { bg: "rgba(245,158,11,0.1)",  color: "#F59E0B" },
};

function CategoryBadge({ category }) {
  const s = CAT_STYLE[category] || { bg: "rgba(100,116,139,0.1)", color: "#64748B" };
  return (
    <span style={{ fontSize: 11, padding: "2px 8px", borderRadius: 20, fontWeight: 500, background: s.bg, color: s.color }}>
      {category}
    </span>
  );
}

// ── Inline editable text ──────────────────────────────────────────────────
function InlineEdit({ value, onSave, onCancel, placeholder = "" }) {
  const [val, setVal] = useState(value);
  return (
    <input
      autoFocus
      value={val}
      onChange={(e) => setVal(e.target.value)}
      onKeyDown={(e) => {
        if (e.key === "Enter")  onSave(val.trim());
        if (e.key === "Escape") onCancel();
      }}
      onBlur={() => onSave(val.trim())}
      placeholder={placeholder}
      style={{
        fontSize: 13, padding: "3px 8px", borderRadius: "var(--border-radius-md)",
        border: "0.5px solid var(--color-border-secondary)",
        background: "var(--color-background-primary)",
        color: "var(--color-text-primary)", outline: "none", minWidth: 180,
      }}
    />
  );
}

// ── Icon button ────────────────────────────────────────────────────────────
function IconBtn({ icon, onClick, danger = false, title = "", disabled = false }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      title={title}
      style={{
        background: "transparent", border: "none", cursor: disabled ? "not-allowed" : "pointer",
        padding: "3px 5px", borderRadius: "var(--border-radius-sm)",
        color: danger ? "var(--color-text-danger)" : "var(--color-text-secondary)",
        display: "inline-flex", alignItems: "center", opacity: disabled ? 0.4 : 1,
      }}
    >
      <i className={`ti ti-${icon}`} style={{ fontSize: 14 }} />
    </button>
  );
}

// ── Main page ──────────────────────────────────────────────────────────────
export default function SkuNormalisation() {
  const [tab, setTab]           = useState("DISTRIBUTOR"); // "DISTRIBUTOR" | "MT"
  const [catFilter, setCatFilter] = useState("");          // "" | "Namkeen" | "Khakhara"

  const [canonicals, setCanonicals] = useState([]);
  const [unmapped, setUnmapped]     = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState("");

  // Collapsed state per family key "Category||Family"
  const [collapsed, setCollapsed] = useState({});

  // Add canonical form
  const [addingCanonical, setAddingCanonical] = useState(false);
  const [newCat,    setNewCat]    = useState("Namkeen");
  const [newFamily, setNewFamily] = useState("");
  const [newName,   setNewName]   = useState("");
  const [saving,    setSaving]    = useState(false);

  // Edit canonical
  const [editingId,  setEditingId]  = useState(null);
  const [editField,  setEditField]  = useState(null); // "name" | "family" | "category"

  // Add mapping panel
  const [mappingFor,   setMappingFor]   = useState(null); // canonical_id
  const [mappingRaw,   setMappingRaw]   = useState("");
  const [mappingSrc,   setMappingSrc]   = useState("");
  const [mappingFromUnmapped, setMappingFromUnmapped] = useState(false);

  const load = useCallback(() => {
    setLoading(true); setError("");
    Promise.all([
      getSkuCanonical(tab),
      getSkuUnmapped(tab),
    ])
      .then(([c, u]) => { setCanonicals(c); setUnmapped(u.unmapped || []); })
      .catch((e) => setError(e.message || "Failed to load"))
      .finally(() => setLoading(false));
  }, [tab]);

  useEffect(() => { load(); }, [load]);

  // ── Tree grouping ─────────────────────────────────────────────────────────
  // Group: { "Namkeen||Chana Jor": { category, family, items: [canonical, ...] } }
  const groups = {};
  canonicals
    .filter((c) => !catFilter || c.category === catFilter)
    .forEach((c) => {
      const key = `${c.category}||${c.family}`;
      if (!groups[key]) groups[key] = { category: c.category, family: c.family, items: [] };
      groups[key].items.push(c);
    });

  const toggleCollapse = (key) => setCollapsed((p) => ({ ...p, [key]: !p[key] }));

  // ── Add canonical ─────────────────────────────────────────────────────────
  const handleAddCanonical = async () => {
    if (!newName.trim() || !newFamily.trim()) return;
    setSaving(true); setError("");
    try {
      await createSkuCanonical({ category: newCat, family: newFamily.trim(), name: newName.trim() });
      setAddingCanonical(false); setNewFamily(""); setNewName(""); load();
    } catch (e) { setError(e.message || "Failed to create"); }
    finally     { setSaving(false); }
  };

  // ── Edit canonical field ──────────────────────────────────────────────────
  const handleEditSave = async (id, field, value) => {
    if (!value) { setEditingId(null); return; }
    setSaving(true);
    try {
      await updateSkuCanonical(id, { [field]: value });
      setEditingId(null); setEditField(null); load();
    } catch (e) { setError(e.message || "Failed to update"); }
    finally     { setSaving(false); }
  };

  // ── Delete canonical ──────────────────────────────────────────────────────
  const handleDeleteCanonical = async (id, name) => {
    if (!window.confirm(`Delete "${name}" and all its mappings?`)) return;
    setSaving(true);
    try { await deleteSkuCanonical(id); load(); }
    catch (e) { setError(e.message || "Failed to delete"); }
    finally   { setSaving(false); }
  };

  // ── Add mapping ───────────────────────────────────────────────────────────
  const handleAddMapping = async (canonicalId) => {
    if (!mappingRaw.trim() || !mappingSrc.trim()) return;
    setSaving(true); setError("");
    try {
      await createSkuMapping({
        raw_sku: mappingRaw.trim(), canonical_id: canonicalId,
        source_type: tab, source_name: mappingSrc.trim().toUpperCase(),
      });
      setMappingFor(null); setMappingRaw(""); setMappingSrc("");
      setMappingFromUnmapped(false); load();
    } catch (e) { setError(e.message || "Failed to add mapping"); }
    finally     { setSaving(false); }
  };

  // ── Delete mapping ────────────────────────────────────────────────────────
  const handleDeleteMapping = async (mappingId) => {
    setSaving(true);
    try { await deleteSkuMapping(mappingId); load(); }
    catch (e) { setError(e.message || "Failed to delete mapping"); }
    finally   { setSaving(false); }
  };

  return (
    <div style={{ padding: "2rem 2.5rem", maxWidth: 900 }}>

      {/* ── Page header ── */}
      <div style={{ marginBottom: "1.5rem" }}>
        <p style={{ margin: 0, fontWeight: 600, fontSize: 24, color: "var(--color-text-primary)" }}>
          SKU Normalisation
        </p>
        <p style={{ margin: "4px 0 0", fontSize: 14, color: "var(--color-text-secondary)" }}>
          Map raw distributor/MT SKU names to canonical product names.
          The dashboard filter uses only canonical names.
        </p>
      </div>

      {/* ── Tabs + category filter ── */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "1.25rem", flexWrap: "wrap", gap: 10 }}>
        {/* Tabs */}
        <div style={{ display: "flex", gap: 0, border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-md)", overflow: "hidden" }}>
          {["DISTRIBUTOR", "MT"].map((t) => (
            <button key={t} onClick={() => { setTab(t); setCollapsed({}); }}
              style={{
                padding: "7px 18px", fontSize: 13, border: "none", cursor: "pointer",
                background: tab === t ? "var(--color-background-secondary)" : "var(--color-background-primary)",
                color: tab === t ? "var(--color-text-primary)" : "var(--color-text-secondary)",
                fontWeight: tab === t ? 500 : 400,
                borderRight: t === "DISTRIBUTOR" ? "0.5px solid var(--color-border-tertiary)" : "none",
              }}
            >
              {t === "DISTRIBUTOR" ? "Distributor" : "Modern Trade"}
            </button>
          ))}
        </div>

        {/* Category filter + Add button */}
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <select value={catFilter} onChange={(e) => setCatFilter(e.target.value)}
            style={{ fontSize: 13, padding: "5px 8px", borderRadius: "var(--border-radius-md)", border: "0.5px solid var(--color-border-secondary)", background: "var(--color-background-primary)", color: "var(--color-text-primary)" }}>
            <option value="">All categories</option>
            {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
          <button onClick={() => setAddingCanonical(true)} style={S.btnPrimary}>
            <i className="ti ti-plus" style={{ fontSize: 14 }} /> Add Canonical SKU
          </button>
        </div>
      </div>

      {/* ── Error ── */}
      {error && (
        <div style={S.errorBox}>
          <i className="ti ti-circle-x" style={{ fontSize: 13, marginRight: 5 }} />{error}
        </div>
      )}

      {/* ── Add canonical form ── */}
      {addingCanonical && (
        <div style={{ ...S.card, marginBottom: 16, display: "flex", flexWrap: "wrap", gap: 10, alignItems: "flex-end" }}>
          <div style={S.formGroup}>
            <label style={S.label}>Category</label>
            <select value={newCat} onChange={(e) => setNewCat(e.target.value)} style={S.select}>
              {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div style={S.formGroup}>
            <label style={S.label}>Family (e.g. "Chana Jor")</label>
            <input value={newFamily} onChange={(e) => setNewFamily(e.target.value)}
              placeholder="Chana Jor" style={S.input} />
          </div>
          <div style={S.formGroup}>
            <label style={S.label}>Canonical name (e.g. "Chana Jor 72g")</label>
            <input value={newName} onChange={(e) => setNewName(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") handleAddCanonical(); if (e.key === "Escape") setAddingCanonical(false); }}
              placeholder="Chana Jor 72g" style={S.input} />
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            <button onClick={handleAddCanonical} disabled={saving || !newName.trim() || !newFamily.trim()} style={S.btnPrimary}>
              {saving ? "Saving…" : "Save"}
            </button>
            <button onClick={() => { setAddingCanonical(false); setNewFamily(""); setNewName(""); }} style={S.btnGhost}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* ── Tree ── */}
      {loading ? (
        <div style={S.card}><p style={S.muted}>Loading…</p></div>
      ) : Object.keys(groups).length === 0 ? (
        <div style={S.card}><p style={S.muted}>No canonical SKUs yet. Add one above.</p></div>
      ) : (
        Object.entries(groups).map(([key, group]) => {
          const isCollapsed = collapsed[key];
          return (
            <div key={key} style={{ ...S.card, marginBottom: 12 }}>
              {/* Family header row */}
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: isCollapsed ? 0 : 12 }}>
                <button onClick={() => toggleCollapse(key)} style={S.collapseBtn}>
                  <i className={`ti ti-chevron-${isCollapsed ? "right" : "down"}`} style={{ fontSize: 13 }} />
                </button>
                <CategoryBadge category={group.category} />
                <span style={{ fontWeight: 600, fontSize: 14, color: "var(--color-text-primary)" }}>
                  {group.family}
                </span>
                <span style={{ fontSize: 12, color: "var(--color-text-tertiary)" }}>
                  {group.items.length} size variant{group.items.length !== 1 ? "s" : ""}
                </span>
              </div>

              {/* Size variants */}
              {!isCollapsed && group.items.map((canonical) => (
                <div key={canonical.id} style={S.canonicalRow}>
                  {/* Canonical name */}
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                    <i className="ti ti-tag" style={{ fontSize: 13, color: "var(--color-text-tertiary)" }} />
                    {editingId === canonical.id && editField === "name" ? (
                      <InlineEdit
                        value={canonical.name}
                        onSave={(v) => handleEditSave(canonical.id, "name", v)}
                        onCancel={() => { setEditingId(null); setEditField(null); }}
                      />
                    ) : (
                      <span style={{ fontWeight: 500, fontSize: 13, color: "var(--color-text-primary)" }}>
                        {canonical.name}
                      </span>
                    )}
                    <IconBtn icon="pencil" title="Edit name"
                      onClick={() => { setEditingId(canonical.id); setEditField("name"); }} />
                    <IconBtn icon="trash" danger title="Delete canonical SKU"
                      onClick={() => handleDeleteCanonical(canonical.id, canonical.name)} />
                  </div>

                  {/* Mappings */}
                  <div style={{ marginLeft: 22 }}>
                    {canonical.mappings.length === 0 ? (
                      <p style={{ ...S.muted, margin: "0 0 6px" }}>No raw SKUs mapped yet</p>
                    ) : (
                      canonical.mappings.map((m) => (
                        <div key={m.id} style={S.mappingRow}>
                          <i className="ti ti-arrow-right" style={{ fontSize: 11, color: "var(--color-text-tertiary)", flexShrink: 0 }} />
                          <span style={{ fontSize: 12, color: "var(--color-text-primary)", flex: 1 }}>{m.raw_sku}</span>
                          <span style={S.sourceTag}>{m.source_name}</span>
                          <IconBtn icon="x" danger title="Remove mapping"
                            onClick={() => handleDeleteMapping(m.id)} />
                        </div>
                      ))
                    )}

                    {/* Add mapping form */}
                    {mappingFor === canonical.id ? (
                      <div style={{ display: "flex", gap: 6, marginTop: 6, flexWrap: "wrap", alignItems: "center" }}>
                        <input
                          value={mappingRaw}
                          onChange={(e) => setMappingRaw(e.target.value)}
                          placeholder="Raw SKU name from file"
                          style={{ ...S.input, minWidth: 220, flex: 1 }}
                        />
                        <input
                          value={mappingSrc}
                          onChange={(e) => setMappingSrc(e.target.value)}
                          placeholder={tab === "MT" ? "Chain (e.g. RELIANCE)" : "Distributor (e.g. SYNERGY)"}
                          style={{ ...S.input, minWidth: 140 }}
                        />
                        <button onClick={() => handleAddMapping(canonical.id)}
                          disabled={saving || !mappingRaw.trim() || !mappingSrc.trim()} style={S.btnPrimary}>
                          {saving ? "…" : "Add"}
                        </button>
                        <button onClick={() => { setMappingFor(null); setMappingRaw(""); setMappingSrc(""); }} style={S.btnGhost}>
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <button onClick={() => { setMappingFor(canonical.id); setMappingRaw(""); setMappingSrc(""); }}
                        style={S.addMappingBtn}>
                        <i className="ti ti-plus" style={{ fontSize: 12 }} /> Add mapping
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          );
        })
      )}

      {/* ── Unmapped SKUs ── */}
      {unmapped.length > 0 && (
        <div style={{ ...S.card, marginTop: 20 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
            <i className="ti ti-alert-triangle" style={{ fontSize: 15, color: "#F59E0B" }} />
            <span style={{ fontWeight: 600, fontSize: 14, color: "var(--color-text-primary)" }}>
              Unmapped SKUs
            </span>
            <span style={{ fontSize: 12, color: "var(--color-text-tertiary)" }}>
              {unmapped.length} raw SKU{unmapped.length !== 1 ? "s" : ""} not yet assigned to a canonical
            </span>
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {unmapped.map((raw) => (
              <div key={raw} style={S.unmappedChip}>
                <span style={{ fontSize: 12, color: "var(--color-text-secondary)" }}>{raw}</span>
                {/* Quick-map button: opens add-mapping form pre-filled */}
                <button
                  title="Map this SKU to a canonical"
                  onClick={() => {
                    setMappingRaw(raw);
                    setMappingFromUnmapped(true);
                    // Scroll to top
                    window.scrollTo({ top: 0, behavior: "smooth" });
                  }}
                  style={{ background: "transparent", border: "none", cursor: "pointer", padding: "0 4px", color: "var(--color-text-info, #378ADD)", display: "inline-flex", alignItems: "center" }}
                >
                  <i className="ti ti-corner-up-left" style={{ fontSize: 12 }} />
                </button>
              </div>
            ))}
          </div>
          {/* If a raw SKU was chosen from unmapped list, show which canonical to map to */}
          {mappingFromUnmapped && mappingRaw && (
            <div style={{ marginTop: 14, padding: "12px 14px", background: "var(--color-background-secondary)", borderRadius: "var(--border-radius-md)", border: "0.5px solid var(--color-border-tertiary)" }}>
              <p style={{ margin: "0 0 8px", fontSize: 13, fontWeight: 500, color: "var(--color-text-primary)" }}>
                Mapping: <span style={{ color: "var(--color-text-info, #378ADD)" }}>{mappingRaw}</span>
              </p>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                <select
                  style={{ ...S.select, minWidth: 220 }}
                  onChange={(e) => {
                    if (e.target.value) {
                      setMappingFor(e.target.value);
                      setMappingFromUnmapped(false);
                    }
                  }}
                  defaultValue=""
                >
                  <option value="">Select canonical SKU…</option>
                  {canonicals.map((c) => (
                    <option key={c.id} value={c.id}>{c.category} › {c.family} › {c.name}</option>
                  ))}
                </select>
                <input
                  value={mappingSrc}
                  onChange={(e) => setMappingSrc(e.target.value)}
                  placeholder={tab === "MT" ? "Chain (e.g. RELIANCE)" : "Distributor (e.g. SYNERGY)"}
                  style={{ ...S.input, minWidth: 160 }}
                />
                <button onClick={() => { setMappingFromUnmapped(false); setMappingRaw(""); setMappingSrc(""); }} style={S.btnGhost}>
                  Cancel
                </button>
              </div>
            </div>
          )}
        </div>
      )}
      {unmapped.length === 0 && !loading && (
        <div style={{ marginTop: 20, padding: "12px 16px", background: "rgba(16,185,129,0.08)", border: "0.5px solid rgba(16,185,129,0.3)", borderRadius: "var(--border-radius-md)", display: "flex", alignItems: "center", gap: 8 }}>
          <i className="ti ti-circle-check" style={{ fontSize: 15, color: "#10B981" }} />
          <span style={{ fontSize: 13, color: "#10B981", fontWeight: 500 }}>All SKUs are mapped to a canonical name.</span>
        </div>
      )}
    </div>
  );
}

// ── Styles ─────────────────────────────────────────────────────────────────────
const S = {
  card: {
    background: "var(--color-background-primary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: "var(--border-radius-lg)",
    padding: "14px 16px",
  },
  canonicalRow: {
    padding: "10px 12px",
    background: "var(--color-background-secondary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: "var(--border-radius-md)",
    marginBottom: 8,
  },
  mappingRow: {
    display: "flex", alignItems: "center", gap: 8,
    padding: "4px 0",
    borderBottom: "0.5px solid var(--color-border-tertiary)",
  },
  sourceTag: {
    fontSize: 10, padding: "1px 7px", borderRadius: 20, fontWeight: 500,
    background: "rgba(55,138,221,0.1)", color: "var(--color-text-info, #378ADD)",
    flexShrink: 0,
  },
  unmappedChip: {
    display: "inline-flex", alignItems: "center", gap: 4,
    padding: "3px 10px",
    background: "var(--color-background-secondary)",
    border: "0.5px solid var(--color-border-tertiary)",
    borderRadius: 20,
  },
  collapseBtn: {
    background: "transparent", border: "none", cursor: "pointer",
    padding: 2, color: "var(--color-text-tertiary)",
    display: "inline-flex", alignItems: "center",
  },
  addMappingBtn: {
    marginTop: 6, display: "inline-flex", alignItems: "center", gap: 4,
    fontSize: 12, padding: "4px 10px", borderRadius: "var(--border-radius-md)",
    background: "transparent", border: "0.5px solid var(--color-border-secondary)",
    color: "var(--color-text-secondary)", cursor: "pointer",
  },
  muted: { fontSize: 13, color: "var(--color-text-tertiary)", margin: 0 },
  errorBox: {
    marginBottom: 12, padding: "8px 12px", fontSize: 12,
    background: "var(--color-background-danger)", color: "var(--color-text-danger)",
    border: "0.5px solid var(--color-border-danger)",
    borderRadius: "var(--border-radius-md)", display: "flex", alignItems: "center",
  },
  formGroup: { display: "flex", flexDirection: "column", gap: 4 },
  label: { fontSize: 11, fontWeight: 500, color: "var(--color-text-tertiary)", textTransform: "uppercase", letterSpacing: "0.04em" },
  input: {
    fontSize: 13, padding: "5px 8px", borderRadius: "var(--border-radius-md)",
    border: "0.5px solid var(--color-border-secondary)",
    background: "var(--color-background-primary)", color: "var(--color-text-primary)", outline: "none",
  },
  select: {
    fontSize: 13, padding: "5px 8px", borderRadius: "var(--border-radius-md)",
    border: "0.5px solid var(--color-border-secondary)",
    background: "var(--color-background-primary)", color: "var(--color-text-primary)",
  },
  btnPrimary: {
    fontSize: 12, padding: "6px 14px", borderRadius: "var(--border-radius-md)",
    border: "none", cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 5,
    background: "var(--color-text-info, #378ADD)", color: "#fff",
  },
  btnGhost: {
    fontSize: 12, padding: "5px 12px", borderRadius: "var(--border-radius-md)",
    background: "transparent", cursor: "pointer",
    border: "0.5px solid var(--color-border-secondary)", color: "var(--color-text-secondary)",
  },
};
